import{_ as n,C as a,o as l,c as h,j as d,a as o,E as e,a5 as c}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"通知","description":"","frontmatter":{},"headers":[],"relativePath":"components/notification.md","filePath":"components/notification.md","lastUpdated":1787670751000}'),s={name:"components/notification.md"},p={id:"通知",tabindex:"-1"};function f(u,t,m,b,x,g){const r=a("Badge"),i=a("XhDemo");return l(),h("div",null,[d("h1",p,[t[0]||(t[0]=o("通知 ",-1)),e(r,{type:"info",text:"notification"}),t[1]||(t[1]=o()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#通知","aria-label":'Permalink to "通知 <Badge type="info" text="notification" />"'},"​",-1))]),t[3]||(t[3]=c('<p>主动推给用户的一条消息：有标题、有正文，可以带操作按钮。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>系统或他人发起的消息：新评论、审批到达、任务跑完了。</li><li>后台完成的长任务：用户当时可能已经在做别的事。</li><li>一句话讲不完，需要标题加正文两层的信息。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>用户刚点了一下按钮，只要一句结果反馈：用<a href="./toast">轻提示</a>。</li><li>用户必须处理才能继续：用<a href="./dialog">对话框</a>阻断。</li><li>页面内某块区域的常驻状态说明：用<a href="./alert">警告提示</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>九宫格落位，<code>placement</code> 决定这一摞落在哪儿；也可以按条逐个指定。</li><li><code>max</code> 限制每个位置同时显示几条，超出的挤掉最旧的。</li><li>同一个 id 再发一次即就地改写，位置不动，用来做&quot;处理中 → 已完成&quot;。</li><li>每条自带计时与暂停：指针停在卡片上、或焦点落进去时不再走表。</li><li><code>duration</code> 给 0 即常驻不消失，适合需要用户处理的消息。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>create 入队并返回 id，队列里的每条由作者渲染成一条通知；退场窗口走完只收起不删，宿主在 status-change 里把它移出队列</p>',10)),e(i,{src:"notification/01-basic"}),t[4]||(t[4]=d("h3",{id:"落位",tabindex:"-1"},[o("落位 "),d("a",{class:"header-anchor",href:"#落位","aria-label":'Permalink to "落位"'},"​")],-1)),t[5]||(t[5]=d("p",null,"placement 决定这一摞贴视口的哪个角，换的只是 group 上的 data-placement，队列本身不动",-1)),e(i,{src:"notification/02-placement"}),t[6]||(t[6]=d("h3",{id:"就地改写",tabindex:"-1"},[o("就地改写 "),d("a",{class:"header-anchor",href:"#就地改写","aria-label":'Permalink to "就地改写"'},"​")],-1)),t[7]||(t[7]=d("p",null,"同一个 id 再 create 一次是原地改写而不是新弹一条，位置不动；loading 不自动消失，换成 success 才开始倒计时",-1)),e(i,{src:"notification/03-update"}),t[8]||(t[8]=d("h3",{id:"上限与清空",tabindex:"-1"},[o("上限与清空 "),d("a",{class:"header-anchor",href:"#上限与清空","aria-label":'Permalink to "上限与清空"'},"​")],-1)),t[9]||(t[9]=d("p",null,"max 限制每个位置同时显示几条，超出挤掉最旧的；dismissAll 把队列直接倒掉，不走退场窗口",-1)),e(i,{src:"notification/04-max"}),t[10]||(t[10]=d("h3",{id:"手动收走",tabindex:"-1"},[o("手动收走 "),d("a",{class:"header-anchor",href:"#手动收走","aria-label":'Permalink to "手动收走"'},"​")],-1)),t[11]||(t[11]=d("p",null,"create 返回的就是队列身份 id，存下来随时 dismiss 掉那一条；dismiss 直接移出队列，不走退场窗口",-1)),e(i,{src:"notification/05-manual-dismiss"}),t[12]||(t[12]=d("h3",{id:"逐条落位",tabindex:"-1"},[o("逐条落位 "),d("a",{class:"header-anchor",href:"#逐条落位","aria-label":'Permalink to "逐条落位"'},"​")],-1)),t[13]||(t[13]=d("p",null,"单条通知自带 placement 就盖掉 notification 的默认落位；placements 报出眼下有条目的位置，一个位置一摞",-1)),e(i,{src:"notification/06-per-item-placement"}),t[14]||(t[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-notification&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhNotificationGroup</code> <code>XhNotificationItem</code> <code>XhNotificationItemActionTrigger</code> <code>XhNotificationItemCloseTrigger</code> <code>XhNotificationItemDescription</code> <code>XhNotificationItemIndicator</code> <code>XhNotificationItemTitle</code> <code>XhNotificationRoot</code></td></tr><tr><td>组合式函数</td><td><code>useNotification</code></td></tr><tr><td>状态机</td><td><code>notificationMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/notification.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;notification&quot;</code>：<strong><code>root</code></strong> · <strong><code>group</code></strong> · <code>item</code> · <code>item-indicator</code> · <code>item-title</code> · <code>item-description</code> · <code>item-action-trigger</code> · <code>item-close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>NotificationRecord[]</code></td><td></td><td>受控队列：给了就由宿主说了算，内部写入只发 onItemsChange。</td></tr><tr><td><code>defaultItems</code></td><td><code>NotificationRecord[]</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>NotificationPlacement</code></td><td></td><td>默认落位，默认 bottom-end。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>每个位置最多同时留几条，超出挤掉最旧的。不给即不限。</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td></td><td>同一摞内的间距（px），默认 16。</td></tr><tr><td><code>duration</code></td><td><code>number</code></td><td></td><td>单条没写 duration 时的默认停留毫秒。</td></tr><tr><td><code>removeDelay</code></td><td><code>number</code></td><td></td><td>单条没写 removeDelay 时的默认退场窗口毫秒。</td></tr><tr><td><code>pauseOnPageIdle</code></td><td><code>boolean</code></td><td></td><td>页面切到后台时暂停计时，逐条下发给 toast。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;NotificationTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onItemsChange</code></td><td><code>(details: NotificationItemsChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>items-change</code></td><td><code>NotificationItemsChangeDetails</code></td><td>队列变化；detail 为 <code>{ items: NotificationRecord[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhNotificationGroup</code></td><td><code>default</code></td><td><code>NotificationGroupSlotProps</code></td><td></td></tr><tr><td><code>XhNotificationItem</code></td><td><code>default</code></td><td><code>{ item: NotificationItemApi }</code></td><td></td></tr><tr><td><code>XhNotificationRoot</code></td><td><code>default</code></td><td><code>NotificationRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>toStatus(state.get())</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>ITEMS.CREATE</code> · <code>ITEMS.UPDATE</code> · <code>ITEMS.DISMISS</code> · <code>ITEMS.DISMISS_ALL</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useNotification</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visibleNotifications</code></td><td><code>ResolvedNotification[]</code></td><td>max 之内、按加入先后排列的可见条目，已补齐默认值。</td></tr><tr><td><code>placements</code></td><td><code>NotificationPlacement[]</code></td><td>当前有条目的位置，按九宫格固定顺序。作者据此决定渲染哪几个 group。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>getItemsByPlacement</code></td><td><code>(placement: NotificationPlacement) =&gt; ResolvedNotification[]</code></td><td></td></tr><tr><td><code>create</code></td><td><code>(options?: NotificationOptions) =&gt; string</code></td><td>入队并返回 id；同 id 已存在则就地改写，位置不动。</td></tr><tr><td><code>update</code></td><td><code>(id: string, options: Partial&lt;NotificationOptions&gt;) =&gt; void</code></td><td></td></tr><tr><td><code>dismiss</code></td><td><code>(id: string) =&gt; void</code></td><td></td></tr><tr><td><code>dismissAll</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>(props?: NotificationGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/alert/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>group</code></td><td><code>aria-label</code></td><td>props.translations.region</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;region&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>item</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>item</code></td><td><code>aria-live</code></td><td>&#39;assertive&#39; | &#39;polite&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;alert&#39; | &#39;status&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item-close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/notification.css</code> 按部件选择：<code>[data-scope=&quot;notification&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-count</code></td><td>list.length</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>group</code></td><td><code>data-count</code></td><td>group.length</td></tr><tr><td><code>group</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>group</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>item</code></td><td><code>data-paused</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>toStatus(state.get())</td></tr><tr><td><code>item</code></td><td><code>data-tone</code></td><td>toneOf(type)</td></tr><tr><td><code>item</code></td><td><code>data-type</code></td><td>props.type</td></tr><tr><td><code>item-close-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-notification-action-bg</code> · <code>--xh-notification-action-bg-active</code> · <code>--xh-notification-action-bg-hover</code> · <code>--xh-notification-action-border</code> · <code>--xh-notification-action-fg</code> · <code>--xh-notification-action-font-weight</code> · <code>--xh-notification-action-h</code> · <code>--xh-notification-action-px</code> · <code>--xh-notification-action-radius</code> · <code>--xh-notification-bg</code> · <code>--xh-notification-border</code> · <code>--xh-notification-close-bg-active</code> · <code>--xh-notification-close-bg-hover</code> · <code>--xh-notification-close-fg</code> · <code>--xh-notification-close-fg-hover</code> · <code>--xh-notification-close-inset</code> · <code>--xh-notification-close-radius</code> · <code>--xh-notification-close-size</code> · <code>--xh-notification-description-fg</code> · <code>--xh-notification-description-font-size</code> · <code>--xh-notification-fg</code> · <code>--xh-notification-font-size</code> · <code>--xh-notification-gap</code> · <code>--xh-notification-icon-size</code> · <code>--xh-notification-indicator-fg</code> · <code>--xh-notification-indicator-size</code> · <code>--xh-notification-inset</code> · <code>--xh-notification-layer</code> · <code>--xh-notification-leading</code> · <code>--xh-notification-px</code> · <code>--xh-notification-py</code> · <code>--xh-notification-radius</code> · <code>--xh-notification-row-gap</code> · <code>--xh-notification-shadow</code> · <code>--xh-notification-title-fg</code> · <code>--xh-notification-title-font-size</code> · <code>--xh-notification-title-font-weight</code> · <code>--xh-notification-title-leading</code> · <code>--xh-notification-w</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-notification-in</code> · <code>xh-notification-out</code> · <code>xh-notification-spin</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>卡片可以放一个操作按钮（查看详情、撤销），按下即退场。</li><li>队列的增删改一并从根插槽给出，业务代码不必自己维护数组。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>整个应用只挂一个队列，挂在最外层。</li><li>落位躲开固定的操作条与移动端手势区。</li><li>重要的那条把 <code>duration</code> 关掉，让用户自己收走。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿它做操作反馈：一次点击弹出一张两层文本的大卡片，喧宾夺主。</li><li>每个页面各挂一个队列：多摞互相盖。</li><li><code>max</code> 设得太大，一屏被通知占满。</li></ul>',47))])}const N=n(s,[["render",f]]);export{P as __pageData,N as default};
